mapper.select:
select courseware_id, count(*) count_value from kng_study_record where courseware_id in
#{coursewareId}
group by courseware_id

select courseware_id, count(*) total_count, coalesce(sum(case when start_study_time >= #{sevenDaysAgo} then 1 else 0 end), 0) recent_count from kng_study_record where courseware_id in
#{coursewareId}
group by courseware_id

select dept_id, count(distinct user_id) study_count, count(distinct case when study_status = 1 then user_id end) finish_count from kng_study_record where dept_id is not null and courseware_id in
#{coursewareId}
and dept_id in
#{deptId}
group by dept_id
